// うっかり入った不完全エントリを除去（安全策）
// ※ 語彙集のカタカナ・ひらがな語は読みが無い（reading:''）ため、読みの代わりに
//   意味(meaning)を持っていれば有効とみなす。
window.KANJI_DATA = window.KANJI_DATA.filter(function (q) {
  return q && q.word && q.sentence && q.sentence.indexOf('{') !== -1 && (q.reading || q.meaning);
});

// =====================================================
// 難読カテゴリの自動タグ付け（word 一致で cat を付与）
//   特殊音 = 常用字だが意外な音読み
//   熟字訓 = 二字以上で特別な読み・当て字
//   難訓   = 難読・文語的な訓読み
// 既存・新規どちらのエントリにもまとめてタグを付ける。
// =====================================================
(function () {
  var CAT = {
    '特殊音': ['出納','会得','成就','定石','情緒','荘厳','建立','供養','境内','遊説','早急','発足','相好','流布','帰依','権化','律儀','生粋','疾病','由緒','反故','面目','布施','内裏','名跡','静脈','老若','精進','従容','平生','会釈','遊山','成敗','冥利','兵糧','功徳','読経','言質','出来','施主','施行','供物','発心','富貴','声明','追従','云々','一切','荒野','面子','執行','遺言','便乗','貼付','分泌','発端','勤行','金色','権現','女房','上人','精霊','修行','修験','因縁','群青','緑青','世論','観音','発起','発作','白夜','冥福','供花','供応','遊行','拍子','神通力','一言'],
    '熟字訓': ['老舗','為替','数珠','意気地','息吹','海女','河岸','桟敷','五月雨','時雨','稚児','雪崩','祝詞','波止場','二十歳','吹雪','紅葉','木綿','最寄り','行方','寄席','名残','硫黄','陽炎','黄昏','東雲','土産','心地','玄人','素人','相撲','草履','足袋','投網','仲人','野良','日和','太刀','山車','白髪','早乙女','三味線','蚊帳','母屋','十八番','神主','神無月','猛者','大和','弥生','浴衣','若人','早苗','五月','田舎','果物','眼鏡','二十日','一日','竹刀','河豚','硝子','煙草','従兄弟','伯父','伯母','師走','神楽','河原','数寄屋','御神酒','乳母','芝生','健気'],
    '難訓': ['詳らか','恭しい','論う','徐に','与する','与る','恣に','準える','賢しい','蔑ろ','佇む','訝る','憚る','疎か','疎んじる','麗しい','貪る','厳か','全う','潤む','潤す','来す','遣わす','弄する','弄ぶ','綻びる','抗う','詣でる','労る','労う','忌む','侮る','逸る','予て','態と','強ち','序でに','過つ','忌まわしい','敢えて','殊更','専ら','自ずと','翻って','遍く','挙って','円ら','卑しい','疾しい','慎ましい','疎ら','強か','均しく','統べる','労しい','剰え','弄る','与しやすい','概ね','予め','諭す','育む','培う','慈しむ','賄う','顧みる','諮る','賜る','悼む','慕う','滞る','覆す','隔てる','慮る','憂える','煩わしい','甚だしい','憤る','携わる','鍛える']
  };
  var map = {};
  Object.keys(CAT).forEach(function (c) {
    CAT[c].forEach(function (w) { map[w] = c; });
  });
  window.KANJI_DATA.forEach(function (q) {
    if (map[q.word]) q.cat = map[q.word];
  });
})();

